"""Temporary deterministic patch generator for WO88 build branch.

This file is disposable and is never copied to the integration branch.
"""
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{path}: expected one replacement, found {count}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8", newline="\n")


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8", newline="\n")


# --- synthetic_action_arbitration: keep public bench API, delegate physical math.
replace_once(
    "src/vivarium/synthetic_action_arbitration.py",
    "from .goals import GoalService\n",
    "from .goals import GoalService\nfrom .physical_capacity import (\n"
    "    PhysicalCapacityError,\n    PhysicalRequest,\n    evaluate_physical_request,\n)\n",
)
old_block = '''@dataclass(frozen=True)\nclass PhysicalCostRequest:\n    \"\"\"Demande explicite au futur owner P, sans ecriture de P dans ce lot.\"\"\"\n\n    operation: Literal[\"activity\", \"traversal\"]\n    physical_load_class: Literal[\"none\", \"light\", \"moderate\", \"vigorous\"] | None = None\n    edge_count: int | None = None\n\n    def __post_init__(self) -> None:\n        if self.operation == \"activity\":\n            if self.physical_load_class not in _LOAD_CLASSES or self.edge_count is not None:\n                raise SyntheticActionArbitrationError(\"demande d'activite physique invalide\", code=\"invalid_physical_request\")\n        elif self.operation == \"traversal\":\n            if self.physical_load_class is not None or isinstance(self.edge_count, bool) \\\n                    or not isinstance(self.edge_count, int) or self.edge_count < 1:\n                raise SyntheticActionArbitrationError(\"demande de traversee physique invalide\", code=\"invalid_physical_request\")\n        else:\n            raise SyntheticActionArbitrationError(\"operation physique invalide\", code=\"invalid_physical_request\")\n\n\n@dataclass(frozen=True)\nclass PhysicalCostEvaluation:\n    feasible: bool\n    required_capacity_milli: int\n    cost_milli: int\n    reason_code: Literal[\"physical_capacity_ok\", \"physical_capacity_insufficient\"]\n\n\ndef evaluate_physical_cost(\n    policy: PhysicalCapacityPolicy, request: PhysicalCostRequest, *, capacity_milli: Any\n) -> PhysicalCostEvaluation:\n    \"\"\"Evalue une requete P sans muter d'etat ni consulter le legacy.\"\"\"\n    capacity = _milli(capacity_milli, field=\"capacite physique\")\n    if request.operation == \"activity\":\n        assert request.physical_load_class is not None\n        load = request.physical_load_class\n        required = int(policy.minimum_capacity_milli[load])\n        cost = int(policy.activity_cost_per_hour_milli[load])\n    else:\n        assert request.edge_count is not None\n        required = int(policy.traversal_cost_per_edge_milli) * request.edge_count\n        cost = required\n    feasible = capacity >= required\n    return PhysicalCostEvaluation(\n        feasible, required, cost,\n        \"physical_capacity_ok\" if feasible else \"physical_capacity_insufficient\",\n    )\n'''
new_block = '''@dataclass(frozen=True)\nclass PhysicalCostRequest(PhysicalRequest):\n    \"\"\"Adaptateur historique du banc vers le contrat P commun.\"\"\"\n\n    def __post_init__(self) -> None:\n        try:\n            super().__post_init__()\n        except PhysicalCapacityError as exc:\n            raise SyntheticActionArbitrationError(str(exc), code=exc.code) from exc\n\n\n@dataclass(frozen=True)\nclass PhysicalCostEvaluation:\n    \"\"\"Compatibilite du banc; ``cost_milli`` n'est pas utilise par le runtime.\"\"\"\n\n    feasible: bool\n    required_capacity_milli: int\n    cost_milli: int\n    reason_code: Literal[\"physical_capacity_ok\", \"physical_capacity_insufficient\"]\n\n\ndef evaluate_physical_cost(\n    policy: PhysicalCapacityPolicy, request: PhysicalCostRequest, *, capacity_milli: Any\n) -> PhysicalCostEvaluation:\n    \"\"\"Adapte l'ancien resultat de banc sans dupliquer les maths P.\"\"\"\n    try:\n        result = evaluate_physical_request(policy, request, capacity_milli=capacity_milli)\n    except PhysicalCapacityError as exc:\n        raise SyntheticActionArbitrationError(str(exc), code=exc.code) from exc\n    cost = (\n        result.activity_rate_milli_per_hour\n        if request.operation == \"activity\"\n        else result.traversal_cost_milli\n    )\n    assert cost is not None\n    return PhysicalCostEvaluation(\n        result.feasible, result.required_capacity_milli, cost, result.reason_code\n    )\n'''
replace_once("src/vivarium/synthetic_action_arbitration.py", old_block, new_block)

# --- sleep_physiology: owner-backed P materialization, still sole persistent owner.
replace_once(
    "src/vivarium/sleep_physiology.py",
    "from .db import transaction\n",
    "from .db import transaction\nfrom .physical_capacity import (\n"
    "    PhysicalCapacityError,\n    advance_physical_capacity,\n)\n",
)
replace_once(
    "src/vivarium/sleep_physiology.py",
    '''@dataclass(frozen=True)\nclass SyntheticMaterialization:\n    \"\"\"Résultat d'un segment de banc ; jamais une activité ou un événement.\"\"\"\n\n    projection: PhysiologyProjection\n    changed: bool\n\n\n''',
    '''@dataclass(frozen=True)\nclass OwnerBackedMaterialization:\n    \"\"\"Matérialisation runtime depuis des causes canoniques relues.\"\"\"\n\n    projection: PhysiologyProjection\n    changed: bool\n    input_fingerprint: str\n    physical_load_class: Literal[\"none\", \"light\", \"moderate\", \"vigorous\"]\n\n\n@dataclass(frozen=True)\nclass SyntheticMaterialization:\n    \"\"\"Résultat d'un segment de banc ; jamais une activité ou un événement.\"\"\"\n\n    projection: PhysiologyProjection\n    changed: bool\n\n\n''',
)
marker = '''    def materialize_synthetic(\n        self,\n        world_id: Any,\n        character_key: Any,\n        at_time: Any,\n        source: RegulationInput,\n    ) -> SyntheticMaterialization:\n'''
insert = '''    def _owner_backed_regime(\n        self, world_id: int, character_key: str\n    ) -> tuple[Literal[\"wake\", \"rest\", \"sleep\"], str, bool, str | None]:\n        \"\"\"Relit l'activité objective qui gouverne le segment courant.\"\"\"\n        character = self._character(world_id, character_key)\n        row = self._conn.execute(\n            \"SELECT a.type, d.physical_load_class, d.requires_sustained_wakefulness \"\n            \"FROM activity a LEFT JOIN activity_definition d \"\n            \"ON d.world_id=a.world_id AND d.activity_type=a.type \"\n            \"WHERE a.world_id=? AND a.character_id=? AND a.status='active' \"\n            \"ORDER BY a.id DESC LIMIT 1\",\n            (world_id, character[\"id\"]),\n        ).fetchone()\n        if row is None:\n            return \"wake\", \"none\", False, None\n        activity_type = row[\"type\"]\n        load = row[\"physical_load_class\"]\n        wakefulness = row[\"requires_sustained_wakefulness\"]\n        if load not in _PHYSICAL_LOAD_CLASSES:\n            raise SleepPhysiologyError(\n                \"classe physique d'activité absente\", code=\"activity_physical_class_missing\"\n            )\n        if wakefulness not in (0, 1):\n            raise SleepPhysiologyError(\n                \"métadonnée de veille soutenue absente\", code=\"activity_wakefulness_missing\"\n            )\n        state: Literal[\"wake\", \"rest\", \"sleep\"] = (\n            \"sleep\" if activity_type == \"sleep\" else \"rest\" if activity_type == \"rest\" else \"wake\"\n        )\n        return state, str(load), bool(wakefulness), str(activity_type)\n\n    def _assert_no_unmaterialized_character_boundary(\n        self, world_id: int, character_key: str, anchor_at: str, target_at: str\n    ) -> None:\n        \"\"\"Falsifie un changement de cause déjà canonisé après l'ancre P/H/phi.\"\"\"\n        row = self._conn.execute(\n            \"SELECT seq,event_type,occurred_at FROM canonical_event \"\n            \"WHERE world_id=? AND occurred_at>? AND occurred_at<=? \"\n            \"AND event_type IN ('character_moved','activity_started','activity_completed','activity_aborted') \"\n            \"AND json_extract(payload,'$.character')=? ORDER BY seq LIMIT 1\",\n            (world_id, anchor_at, target_at, character_key),\n        ).fetchone()\n        if row is not None:\n            raise SleepPhysiologyError(\n                \"frontière causale non matérialisée avant mutation\",\n                code=\"unmaterialized_causal_boundary\",\n            )\n\n    def materialize_owner_backed(\n        self,\n        world_id: Any,\n        character_key: Any,\n        at_time: Any | None = None,\n    ) -> OwnerBackedMaterialization:\n        \"\"\"Matérialise H/phi/P jusqu'à une frontière canonique déjà atteinte.\n\n        L'appelant ne fournit aucune cause physiologique. Le lieu, l'activité,\n        la lumière et la classe physique sont relus depuis leurs owners. Le\n        service reste l'unique écrivain persistant de H/phi/P/résidus/hystérésis.\n        \"\"\"\n        world = self._world_id(world_id)\n        character = _key(character_key, field=\"personnage\")\n        target = _at(at_time or WorldEngine(self._conn, clock=self._clock).read_canonical_time(world))\n        live = _at(WorldEngine(self._conn, clock=self._clock).read_canonical_time(world))\n        if parse_iso(target) > parse_iso(live):\n            raise SleepPhysiologyError(\n                \"frontière physiologique future\", code=\"stale_canonical_anchor\"\n            )\n        with transaction(self._conn) as conn:\n            state = self.read_state(world, character)\n            duration = self._seconds_between(state.anchor_at, target)\n            self._assert_no_unmaterialized_character_boundary(\n                world, character, state.anchor_at, target\n            )\n            regime, load, _sustained, activity_type = self._owner_backed_regime(world, character)\n            location = self._conn.execute(\n                \"SELECT l.key FROM character ch JOIN location l ON l.id=ch.current_location_id \"\n                \"WHERE ch.world_id=? AND ch.key=?\", (world, character)\n            ).fetchone()\n            if location is None:\n                raise SleepPhysiologyError(\n                    \"position canonique absente\", code=\"canonical_position_missing\"\n                )\n            source, metadata = self._resolve_light_source_values(\n                world, location[\"key\"], state.anchor_at, state=regime\n            )\n            fingerprint_payload = {\n                \"world_id\": world, \"character_key\": character,\n                \"anchor_at\": state.anchor_at, \"target_at\": target,\n                \"location_key\": location[\"key\"], \"activity_type\": activity_type,\n                \"physical_load_class\": load, \"light\": metadata,\n            }\n            fingerprint = hashlib.sha256(json.dumps(\n                fingerprint_payload, sort_keys=True, separators=(\",\", \":\"), ensure_ascii=False\n            ).encode(\"utf-8\")).hexdigest()\n            if duration == 0:\n                projection = self.project_synthetic(world, character, source)\n                return OwnerBackedMaterialization(projection, False, fingerprint, load)\n\n            parameters = self.parameters_for_character(world, character)\n            policy = SleepPhysiologyFoundationService(\n                self._conn, clock=self._clock\n            ).validate_physical_capacity_configuration(world)\n            regulation = state.regulation\n            band = state.previous_stability_band\n            stability = wake_stability(regulation, source, parameters, previous_band=band)\n            remaining = duration\n            while remaining:\n                quantum = min(SYNTHETIC_INTEGRATION_QUANTUM_SECONDS, remaining)\n                advanced = advance_regulation(regulation, source, quantum, parameters)\n                regulation = RegulationState(\n                    advanced.homeostatic_load, advanced.circadian_phase,\n                    regulation.physical_capacity,\n                )\n                stability = wake_stability(\n                    regulation, source, parameters, previous_band=band\n                )\n                band = stability.band\n                remaining -= quantum\n            try:\n                capacity_milli, remainder = advance_physical_capacity(\n                    policy, capacity_milli=state.regulation.physical_capacity_milli,\n                    rate_remainder=state.physical_capacity_remainder, state=regime,\n                    physical_load_class=load, duration_seconds=duration,\n                )\n            except PhysicalCapacityError as exc:\n                raise SleepPhysiologyError(str(exc), code=exc.code) from exc\n            regulation = RegulationState(\n                regulation.homeostatic_load, regulation.circadian_phase,\n                capacity_milli / 100000.0,\n            )\n            homeostatic_milli, phase_milli, homeostatic_residue, phase_residue = (\n                self._precision_projection(regulation)\n            )\n            character_row = self._character(world, character)\n            now = self._now()\n            conn.execute(\n                \"UPDATE sleep_regulation_state SET homeostatic_load_milli=?,circadian_phase_milli=?,\"\n                \"anchor_at=?,updated_at=? WHERE world_id=? AND character_id=?\",\n                (homeostatic_milli, phase_milli, target, now, world, character_row[\"id\"]),\n            )\n            conn.execute(\n                \"UPDATE physical_capacity_state SET capacity_milli=?,rate_remainder=?,anchor_at=?,updated_at=? \"\n                \"WHERE world_id=? AND character_id=?\",\n                (capacity_milli, remainder, target, now, world, character_row[\"id\"]),\n            )\n            hysteresis = conn.execute(\n                \"UPDATE sleep_wake_hysteresis_state SET previous_band=?,anchor_at=?,updated_at=? \"\n                \"WHERE world_id=? AND character_id=?\",\n                (band, target, now, world, character_row[\"id\"]),\n            )\n            precision = conn.execute(\n                \"UPDATE sleep_regulation_precision_state SET homeostatic_load_residue=?,\"\n                \"circadian_phase_residue=?,anchor_at=?,updated_at=? WHERE world_id=? AND character_id=?\",\n                (homeostatic_residue, phase_residue, target, now, world, character_row[\"id\"]),\n            )\n            if hysteresis.rowcount != 1:\n                raise SleepPhysiologyError(\n                    \"mémoire d'hystérésis absente\", code=\"hysteresis_state_missing\"\n                )\n            if precision.rowcount != 1:\n                raise SleepPhysiologyError(\n                    \"résidu d'intégration absent\", code=\"precision_state_missing\"\n                )\n        projection = PhysiologyProjection(\n            PersistedPhysiologyState(\n                state.model_key, state.model_version, regulation, target, remainder,\n                homeostatic_residue, phase_residue, band,\n            ),\n            sleep_propensity(regulation, parameters, family=\"additive\"),\n            stability,\n        )\n        return OwnerBackedMaterialization(projection, True, fingerprint, load)\n\n'''
replace_once("src/vivarium/sleep_physiology.py", marker, insert + marker)

write(
    "tests/test_active_physical_capacity.py",
    '''"""WO88A : noyau P commun et matérialisation owner-backed."""\n\nfrom dataclasses import asdict\nfrom datetime import datetime, timezone\n\nimport pytest\n\nfrom vivarium.circadian_model import calibration_profiles\nfrom vivarium.db import connect_database, transaction\nfrom vivarium.integration_world import IntegrationWorldService\nfrom vivarium.migrations import ensure_schema\nfrom vivarium.physical_capacity import (\n    PhysicalCapacityError, PhysicalRequest, advance_physical_capacity,\n    evaluate_physical_request,\n)\nfrom vivarium.sleep_physiology import (\n    ADDITIVE_MODEL_KEY, SleepPhysiologyFoundationService, SleepPhysiologyService,\n)\nfrom vivarium.world import WorldEngine\n\nANCHOR = "2026-08-11T12:00:00+00:00"\nT30 = "2026-08-11T12:00:30+00:00"\nT60 = "2026-08-11T12:01:00+00:00"\n\n\ndef _profile_payload():\n    payload = asdict(calibration_profiles()["human_reference_candidate.v1"])\n    for key in ("profile_key", "version", "evidence_class"):\n        payload.pop(key)\n    return {"model_key": ADDITIVE_MODEL_KEY, "parameters": payload}\n\n\ndef _policy():\n    return {\n        "schema_version": 1,\n        "activity_cost_per_hour_milli": {\n            "none": 3600, "light": 7200, "moderate": 10800, "vigorous": 18000,\n        },\n        "minimum_capacity_milli": {\n            "none": 0, "light": 10000, "moderate": 25000, "vigorous": 45000,\n        },\n        "traversal_cost_per_edge_milli": 250,\n        "recovery_per_hour_milli": {"rest": 7200, "sleep": 10800},\n    }\n\n\ndef test_activity_rate_and_traversal_cost_are_distinct_contracts():\n    class Policy:\n        activity_cost_per_hour_milli = _policy()["activity_cost_per_hour_milli"]\n        minimum_capacity_milli = _policy()["minimum_capacity_milli"]\n        traversal_cost_per_edge_milli = 250\n        recovery_per_hour_milli = _policy()["recovery_per_hour_milli"]\n\n    activity = evaluate_physical_request(\n        Policy(), PhysicalRequest("activity", physical_load_class="moderate"),\n        capacity_milli=30_000,\n    )\n    traversal = evaluate_physical_request(\n        Policy(), PhysicalRequest("traversal", edge_count=3), capacity_milli=30_000,\n    )\n    assert activity.activity_rate_milli_per_hour == 10_800\n    assert activity.traversal_cost_milli is None\n    assert traversal.activity_rate_milli_per_hour is None\n    assert traversal.traversal_cost_milli == 750\n\n\ndef test_capacity_time_integration_is_partition_stable_and_saturation_resets_remainder():\n    class Policy:\n        activity_cost_per_hour_milli = _policy()["activity_cost_per_hour_milli"]\n        minimum_capacity_milli = _policy()["minimum_capacity_milli"]\n        traversal_cost_per_edge_milli = 250\n        recovery_per_hour_milli = _policy()["recovery_per_hour_milli"]\n\n    single = advance_physical_capacity(\n        Policy(), capacity_milli=70_000, rate_remainder=0, state="wake",\n        physical_load_class="moderate", duration_seconds=61,\n    )\n    first = advance_physical_capacity(\n        Policy(), capacity_milli=70_000, rate_remainder=0, state="wake",\n        physical_load_class="moderate", duration_seconds=17,\n    )\n    split = advance_physical_capacity(\n        Policy(), capacity_milli=first[0], rate_remainder=first[1], state="wake",\n        physical_load_class="moderate", duration_seconds=44,\n    )\n    assert split == single\n    assert advance_physical_capacity(\n        Policy(), capacity_milli=99_999, rate_remainder=3599, state="sleep",\n        physical_load_class="none", duration_seconds=1,\n    ) == (100_000, 0)\n    with pytest.raises(PhysicalCapacityError):\n        PhysicalRequest("traversal", edge_count=0)\n\n\ndef _active_world():\n    conn = connect_database(":memory:")\n    ensure_schema(conn)\n    world_id = IntegrationWorldService(conn).create_initial_world()["id"]\n    foundation = SleepPhysiologyFoundationService(conn)\n    foundation.register_light_schedule("active.day.v1", 1, {\n        "schema_version": 1,\n        "segments": [{"start_second": 0, "end_second": 86400, "environmental_light_milli": 50000}],\n    })\n    foundation.register_location_light_profile("active.interior.v1", 1, 25000, {"kind": "interior"})\n    foundation.register_biology_profile("active.human.v1", 1, "human_reference", _profile_payload())\n    foundation.register_physical_capacity_policy("active.capacity.v1", 1, _policy(), "test")\n    foundation.assign_light_schedule(world_id, "active.day.v1", 1, ANCHOR, "test")\n    for row in conn.execute("SELECT key FROM location WHERE world_id=? ORDER BY key", (world_id,)):\n        foundation.assign_location_light_profile(world_id, row["key"], "active.interior.v1", 1, ANCHOR, "test")\n    for row in conn.execute("SELECT key FROM character WHERE world_id=? ORDER BY key", (world_id,)):\n        foundation.assign_biology_profile(world_id, row["key"], "active.human.v1", 1, "test")\n    foundation.assign_physical_capacity_policy(world_id, "active.capacity.v1", 1, "test")\n    # Explicit metadata belongs to the activity catalogue, even though this test\n    # leaves every character without an active activity.\n    conn.execute(\n        "UPDATE activity_definition SET physical_load_class='none' WHERE world_id=?", (world_id,)\n    )\n    foundation.prepare_world(world_id, ADDITIVE_MODEL_KEY, 1, "test")\n    with transaction(conn) as tx:\n        tx.execute(\n            "UPDATE world_physiology_system SET status='active',activated_at=?,activated_by=?,updated_at=? WHERE world_id=?",\n            (ANCHOR, "test", ANCHOR, world_id),\n        )\n        for row in tx.execute("SELECT id FROM character WHERE world_id=? ORDER BY id", (world_id,)):\n            cid = row["id"]\n            tx.execute(\n                "INSERT INTO sleep_regulation_state (public_id,world_id,character_id,model_key,model_version,homeostatic_load_milli,circadian_phase_milli,anchor_at,updated_at) VALUES (?,?,?,?,1,50000,250000,?,?)",\n                (f"reg-{cid}", world_id, cid, ADDITIVE_MODEL_KEY, ANCHOR, ANCHOR),\n            )\n            tx.execute(\n                "INSERT INTO physical_capacity_state (public_id,world_id,character_id,capacity_milli,rate_remainder,anchor_at,updated_at) VALUES (?,?,?,70000,0,?,?)",\n                (f"cap-{cid}", world_id, cid, ANCHOR, ANCHOR),\n            )\n            tx.execute(\n                "INSERT INTO sleep_wake_hysteresis_state (public_id,world_id,character_id,previous_band,anchor_at,updated_at) VALUES (?,?,?,'fragile',?,?,?)",\n                (f"hys-{cid}", world_id, cid, ANCHOR, ANCHOR, ANCHOR),\n            )\n            tx.execute(\n                "INSERT INTO sleep_regulation_precision_state (public_id,world_id,character_id,homeostatic_load_residue,circadian_phase_residue,anchor_at,updated_at) VALUES (?,?,?,0.0,0.0,?,?)",\n                (f"pre-{cid}", world_id, cid, ANCHOR, ANCHOR),\n            )\n    return conn, world_id\n\n\ndef test_owner_backed_materialization_uses_policy_p_and_is_partition_stable():\n    conn, world_id = _active_world()\n    try:\n        service = SleepPhysiologyService(conn)\n        with transaction(conn) as tx:\n            WorldEngine(conn)._advance_clock(world_id, T30, tx)\n        first = service.materialize_owner_backed(world_id, "sophie", T30)\n        assert first.changed and first.physical_load_class == "none"\n        assert first.projection.state.regulation.physical_capacity_milli == 69_970\n        with transaction(conn) as tx:\n            WorldEngine(conn)._advance_clock(world_id, T60, tx)\n        split = service.materialize_owner_backed(world_id, "sophie", T60)\n        single = service.materialize_owner_backed(world_id, "erika", T60)\n        assert split.projection.state.regulation.physical_capacity_milli == 69_940\n        assert single.projection.state.regulation.physical_capacity_milli == 69_940\n        assert split.projection.state.regulation.homeostatic_load_milli == single.projection.state.regulation.homeostatic_load_milli\n        assert split.projection.state.regulation.circadian_phase_milli == single.projection.state.regulation.circadian_phase_milli\n        again = service.materialize_owner_backed(world_id, "sophie", T60)\n        assert not again.changed\n    finally:\n        conn.close()\n''',
)
